import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

@OptIn(ExperimentalEncodingApi::class)
internal actual fun readYtEjsSolverScript(fileName: String): String =
    when (fileName) {
        "yt.solver.core.min.js" -> Base64.decode(YT_SOLVER_CORE_B64).decodeToString()
        "yt.solver.lib.min.js" -> Base64.decode(YT_SOLVER_LIB_B64).decodeToString()
        else -> error("Missing embedded script: $fileName")
    }

